// Constantes de autoria por origen. Este workflow SOLO sirve al CMS: por eso author_id
// y origen son constantes aqui y no pueden confundirse con los del pipeline RSS.
const AUTOR_MANUAL = 6;      // Moises Orraiz
const ORIGEN = 'cms';
const body = ($json && typeof $json.body === 'object' && $json.body !== null) ? $json.body : $json;
const texto = (v) => (typeof v === 'string' ? v.trim() : '');
const titular = texto(body.titular);
const cuerpo = texto(body.cuerpo);
const solicitado_por = texto(body.solicitado_por);
// Imagenes que puso el editor entre los parrafos (el texto lleva solo marcadores [[IMG:n]]). Solo se aceptan las del
// bucket propio: lo mismo que exige el sitio al guardar.
const BUCKET = 'https://pudzvatuubywmwdmboiq.supabase.co/storage/v1/object/public/post-images/';
const numero = (v) => (Number(v) > 0 ? Number(v) : null);
const imagenes = (Array.isArray(body.imagenes) ? body.imagenes : []).slice(0, 10)
  .map((i) => ({ n: Number(i && i.n), url: texto(i && i.url), alt: texto(i && i.alt).slice(0, 300), caption: texto(i && i.caption).slice(0, 300), width: numero(i && i.width), height: numero(i && i.height) }))
  .filter((i) => Number.isInteger(i.n) && i.n >= 1 && i.url.startsWith(BUCKET) && !i.url.slice(BUCKET.length).includes('..'));
const visible = cuerpo.replace(/\[\[IMG:\d+\]\]/g, ' ').replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
const errores = [];
if (!titular) errores.push('El titular es obligatorio.');
else if (titular.length > 200) errores.push('El titular no puede pasar de 200 caracteres (tiene ' + titular.length + ').');
if (!cuerpo) errores.push('El cuerpo es obligatorio.');
else if (visible.length < 200) errores.push('El cuerpo necesita al menos 200 caracteres (tiene ' + visible.length + ').');
return [{ json: {
  valido: errores.length === 0,
  error: errores.join(' '),
  titular,
  cuerpo,
  imagenes,
  solicitado_por,
  author_id: AUTOR_MANUAL,
  origen: ORIGEN
} }];

