let data = $json.output?.[0]?.content?.[0]?.text ?? $json.choices?.[0]?.message?.content ?? $json.message?.content ?? $json.text;
if (typeof data === 'string') {
  data = data.trim().replace(/^```json\s*/i, '').replace(/```\s*$/, '');
  data = JSON.parse(data);
}
if (!data || typeof data !== 'object') throw new Error('El analisis no devolvio un JSON interpretable.');
const entrada = $('Normalizar entrada').first().json;
const tagRows = $('Obtener tags').first().json.body || [];
const slugify = (s) => (s == null ? '' : String(s)).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 80).replace(/-+$/g, '');
const title = String(data.title || entrada.titular).trim().slice(0, 200);
const slug_base = slugify(data.slug || title) || 'articulo-' + $now.toFormat('yyyyMMddHHmmss');
const content_html_gpt = typeof data.content_html === 'string' ? data.content_html.trim() : '';
if (!content_html_gpt) throw new Error('El analisis no devolvio content_html.');
// Imagenes del editor: cada marcador [[IMG:n]] se cambia por su <figure>. Las URL, el alt y el pie salen de lo que mando
// el editor, no de GPT. Si GPT se comio un marcador, la imagen se anade al final en vez de perderse.
const imagenesEditor = Array.isArray(entrada.imagenes) ? entrada.imagenes : [];
const escAttr = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const escText = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const figura = (im) => '<figure><img src="' + escAttr(im.url) + '" alt="' + escAttr(im.alt) + '"' + (im.width ? ' width="' + im.width + '"' : '') + (im.height ? ' height="' + im.height + '"' : '') + '>' + (im.caption ? '<figcaption>' + escText(im.caption) + '</figcaption>' : '') + '</figure>';
const usadas = new Set();
let content_html = content_html_gpt.replace(/<p>\s*\[\[IMG:(\d+)\]\]\s*<\/p>|\[\[IMG:(\d+)\]\]/g, (m, a, b) => {
  const n = Number(a || b);
  const im = imagenesEditor.find((x) => x.n === n);
  if (!im || usadas.has(n)) return '';
  usadas.add(n);
  return figura(im);
});
content_html += imagenesEditor.filter((im) => !usadas.has(im.n)).map(figura).join('');
content_html = content_html.replace(/\[\[IMG:[^\]]*\]\]/g, '');
const original_locale = ['es', 'en'].includes(String(data.original_locale || '').toLowerCase()) ? String(data.original_locale).toLowerCase() : 'es';
const sentimentMap = { bullish: 'bullish', bearish: 'bearish', neutral: 'neutral', Bullish: 'bullish', Bearish: 'bearish', Neutral: 'neutral', Neutro: 'neutral' };
const sentiment = sentimentMap[data.sentiment] || 'neutral';
const categoryMap = { 'criptomonedas': 1, 'forex': 2, 'materias-primas': 3, 'acciones': 4 };
const category_id = categoryMap[slugify(data.category)] || 1;
// Mapeo de etiquetas: SOLO las que existen en la tabla tags. Acepta slug o nombre; nunca inventa.
const permitidos = new Map();
for (const t of tagRows) { permitidos.set(t.slug, t.id); permitidos.set(slugify(t.name), t.id); }
const pedidos = Array.isArray(data.tags) ? data.tags : [];
const tag_ids = [...new Set(pedidos.map((t) => permitidos.get(slugify(t))).filter((v) => v != null))].slice(0, 3);
const tags_descartadas = pedidos.filter((t) => !permitidos.has(slugify(t)));
const plainText = content_html_gpt.replace(/\[\[IMG:\d+\]\]/g, ' ').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
const format = plainText.length < 350 ? 'brief' : 'article';
const wordCount = plainText ? plainText.split(' ').filter(Boolean).length : 0;
const reading_time_minutes = Math.max(1, Math.ceil(wordCount / 200));
const meta_description = String(data.meta_description || title).trim().slice(0, 160);
const meta_title = String(data.meta_title || title).trim().slice(0, 200);
return [{ json: {
  title, slug_base, content_html, meta_title, meta_description, sentiment, category_id,
  original_locale, format, reading_time_minutes, tag_ids, tags_descartadas,
  prompt_imagen: data.prompt_imagen || 'A single large smooth brushed-metal disc resting on coarse stone, with one hairline crack across its surface, no markings of any kind',
  author_id: entrada.author_id, origen: entrada.origen, solicitado_por: entrada.solicitado_por
} }];

