let data = $json.output?.[0]?.content?.[0]?.text ?? $json.choices?.[0]?.message?.content ?? $json.message?.content ?? $json.text;
if (typeof data === 'string') {
  data = data.trim().replace(/^```json\s*/i, '').replace(/```\s*$/, '');
  data = JSON.parse(data);
}
if (!data || typeof data !== 'object') throw new Error('La traduccion no devolvio un JSON interpretable.');
const o = $('Resolver slug').first().json;
const slugify = (s) => (s == null ? '' : String(s)).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 80).replace(/-+$/g, '');
const locale_original = o.original_locale;
const locale_opuesto = locale_original === 'es' ? 'en' : 'es';
const title = String(data.title || o.title).trim().slice(0, 200);
const content_html = typeof data.content_html === 'string' ? data.content_html.trim() : '';
if (!content_html) throw new Error('La traduccion no devolvio content_html.');
return [{ json: {
  post_id: $('Insertar post').first().json.id,
  locale_original, locale_opuesto,
  original: { title: o.title, slug: o.slug, content_html: o.content_html, meta_title: o.meta_title, meta_description: o.meta_description },
  traducida: {
    title,
    slug_base: slugify(data.slug || title) || o.slug + '-' + locale_opuesto,
    content_html,
    meta_title: String(data.meta_title || title).trim().slice(0, 200),
    meta_description: String(data.meta_description || title).trim().slice(0, 160)
  }
} }];

// UNIQUE(locale, slug): el slug traducido solo tiene que estar libre DENTRO de su locale.
// Que coincida con el slug del original en el otro idioma es legal y deseable.
const t = $('Parsear traduccion').first().json;
const usados = new Set();
for (const r of ($('Slugs en uso · locale opuesto').first().json.body || [])) if (r && r.slug) usados.add(r.slug);
const base = t.traducida.slug_base;
let slug = base;
for (let i = 2; usados.has(slug) && i <= 60; i++) slug = base + '-' + i;
if (usados.has(slug)) slug = base + '-' + Date.now().toString(36);
return [{ json: { ...t, traducida: { ...t.traducida, slug }, slug_traducido_colisiono: slug !== base } }];

